  "primary_collocate": "close observation",
  "collocation_distractors": [
    {
      "word": "narrow observation",
      "explanation": "English uses 'close' or 'detailed' to describe intense scrutiny; 'narrow' implies limited scope rather than high scrutiny."
    },
    {
      "word": "tight observation",
      "explanation": "'Tight' collocates with 'security' or 'control', but is unidiomatic when describing the act of monitoring or observing."
    },
    {
      "word": "hard observation",
      "explanation": "Learners confuse 'take a hard look' with 'observation', producing an unnatural adjectival pairing."
    }
